package dev.pocketengine.ui;

import dev.pocketengine.EngineApplication;
import dev.pocketengine.features.channels.ChannelsModule;
import dev.pocketengine.features.attachments.AttachmentRepository;
import java.io.ByteArrayInputStream;
import java.net.HttpURLConnection;
import java.net.InetSocketAddress;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import dev.pocketengine.testutil.HttpServer;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.Before;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.android.controller.ActivityController;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;

/** Real Activity/Controller/Application, authenticated explicit relay, original SQLite/Runner and HTTP. Not a QQ-account test. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=EngineApplication.class)
public final class GroupNativeApplicationControllerTest {
    @Before public void keys(){java.security.Security.addProvider(new java.security.Provider("GroupMountedKeyStore","1","Explicit test-only AndroidKeyStore"){{put("KeyStore.AndroidKeyStore",dev.pocketengine.features.channels.ChannelTaskHostTest.FixtureKeyStore.class.getName());}});}
    interface Check{boolean done()throws Exception;}
    static void await(Check check)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(!check.done()&&System.nanoTime()<until){Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();Thread.sleep(10);}Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue("actual native group condition not reached",check.done());}
    private static JSONObject j(Object... pairs)throws Exception{JSONObject result=new JSONObject();for(int i=0;i<pairs.length;i+=2)result.put((String)pairs[i],pairs[i+1]);return result;}
    static JSONObject request(PocketWorldController controller,String command,JSONObject payload)throws Exception{String id=controller.requestOwnerDomain("groups",command,payload);await(()->id.equals(controller.getState().ownerResponses("groups").getOrDefault(command,new JSONObject()).optString("requestId")));JSONObject envelope=controller.getState().ownerResponses("groups").get(command);assertTrue(envelope.optString("message",envelope.optString("error")),envelope.getBoolean("ok"));return envelope.getJSONObject("result");}
    @Test public void mountedNativeGroupUsesRealWindowOriginalRunnerAndOneAuthenticatedRelayReply()throws Exception{
        EngineApplication app=(EngineApplication)RuntimeEnvironment.getApplication();AtomicInteger models=new AtomicInteger(),replies=new AtomicInteger();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String secret="0123456789abcdef0123456789abcdef";
        server.createContext("/v1/chat/completions",e->{try{models.incrementAndGet();JSONObject body=new JSONObject(new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));String text=body.toString();assertFalse(text.contains("PRIVATE-GROUP-MOUNT-SENTINEL"));assertFalse(String.valueOf(body.optJSONArray("tools")).contains("memory_"));byte[] bytes=j("choices",new JSONArray().put(j("message",j("role","assistant","content","Actual isolated group answer"),"finish_reason","stop"))).toString().getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().add("Content-Type","application/json");e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);}catch(Exception failure){throw new IllegalStateException(failure);}finally{e.close();}});
        server.createContext("/reply",e->{try{assertEquals("Bearer "+secret,e.getRequestHeaders().getFirst("Authorization"));JSONObject body=new JSONObject(new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));assertEquals("group",body.getString("audience"));assertEquals("room-native",body.getString("roomId"));assertTrue(body.toString().contains("Actual isolated group answer"));replies.incrementAndGet();byte[] bytes=j("id","accepted-original-relay-id").toString().getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);}catch(Exception failure){throw new IllegalStateException(failure);}finally{e.close();}});server.start();String base="http://127.0.0.1:"+server.getAddress().getPort();
        ActivityController<ComposeActivity> activity=null;
        try{app.getSharedPreferences("private_settings",0).edit().putString("baseUrl",base+"/v1").putString("provider","openai_chat").putString("model","group-native-fixture").putInt("maxOutputTokens",256).putInt("maxSteps",8).putBoolean("sendScreenshots",false).commit();AttachmentRepository.get(app).book.importBytes(new ByteArrayInputStream("PRIVATE-GROUP-MOUNT-SENTINEL".getBytes(StandardCharsets.UTF_8)),"private.txt","text/plain",new JSONObject());
            assertTrue(app.features.module("groups").snapshot().getJSONObject("capabilities").getBoolean("groupTasksReady"));assertThrows(SecurityException.class,()->app.groupOwnerSnapshot());assertThrows(SecurityException.class,()->app.features.module("groups").handle("group.create",j("name","forged")));
            ChannelsModule channels=(ChannelsModule)app.features.module("channels");String profile=channels.handle("profile.save",j("name","Native explicit relay","provider","webhook","enabled",true,"replyUrl",base+"/reply","secret",secret)).getString("id");channels.handle("server.start",j("port",0));
            activity=Robolectric.buildActivity(ComposeActivity.class).create().start().resume();ComposeActivity screen=activity.get();java.lang.reflect.Field field=ComposeActivity.class.getDeclaredField("controller");field.setAccessible(true);PocketWorldController controller=(PocketWorldController)field.get(screen);controller.enterOwnerDomain("groups");JSONObject snapshot=request(controller,"snapshot",new JSONObject());assertTrue(snapshot.getJSONArray("nativeConnections").toString().contains(profile));assertFalse(snapshot.getJSONObject("nativeResources").getBoolean("public.search"));assertFalse(snapshot.getJSONObject("nativeResources").getBoolean("media.video"));
            JSONObject group=request(controller,"group.create",j("name","Actual native group","provider","webhook","accountId",profile,"roomId","room-native"));group=request(controller,"member.set",j("id",group.getString("id"),"revision",group.getLong("revision"),"senderId","member-native","displayName","Native member","role","member","enabled",true));JSONObject quota=group.getJSONObject("quota");quota.put("dailyTokens",200000).put("maxTokensPerTask",60000);group=request(controller,"policy.set",j("id",group.getString("id"),"revision",group.getLong("revision"),"enabled",true,"visibility","requester","quota",quota,"grants",new JSONArray().put(j("capability","public.answer","resource","public","allowGroupAudience",true,"expiresAt",System.currentTimeMillis()+3_600_000))));
            byte[] event=j("messageId","original-native-source","senderId","member-native","roomId","room-native","kind","group","text","/task --tokens=60000 Explain one public fact","sentAt",System.currentTimeMillis()).toString().getBytes(StandardCharsets.UTF_8);int port=channels.snapshot().getJSONObject("server").getInt("port");HttpURLConnection inbound=(HttpURLConnection)new URL("http://127.0.0.1:"+port+"/events/"+profile).openConnection();inbound.setRequestMethod("POST");inbound.setDoOutput(true);inbound.setRequestProperty("Authorization","Bearer "+secret);inbound.setRequestProperty("Content-Type","application/json");inbound.setFixedLengthStreamingMode(event.length);try(java.io.OutputStream out=inbound.getOutputStream()){out.write(event);}assertEquals(200,inbound.getResponseCode());inbound.getInputStream().close();inbound.disconnect();
            await(()->app.tasks.list().length()==1&&app.tasks.list().getJSONObject(0).optString("status").equals("completed")&&replies.get()==1);JSONObject task=app.tasks.get(app.tasks.list().getJSONObject(0).getString("id"),false);assertEquals("group",task.getJSONObject("origin").getString("kind"));assertNotEquals("owner",task.getString("actorId"));assertTrue(task.getString("spaceId").startsWith("group:"));assertEquals(1,models.get());assertEquals(1,replies.get());assertFalse(task.toString().contains("PRIVATE-GROUP-MOUNT-SENTINEL"));
            final String id=task.getString("id");assertThrows(SecurityException.class,()->app.dispatchOwnerAction("resumeTask",j("taskId",id)));assertThrows(SecurityException.class,()->app.dispatchOwnerAction("updateTask",j("taskId",id,"feedback","private text must not enter group")));JSONObject inspected=request(controller,"task.inspect",j("requestId",task.getJSONObject("origin").getString("requestId")));assertEquals(id,inspected.getJSONObject("task").getString("taskId"));assertEquals(1,app.tasks.list().length());
            String inspectReceipt=controller.getState().ownerResponses("groups").get("task.inspect").getString("requestId");request(controller,"snapshot",new JSONObject());assertTrue("refresh must not erase the original action receipt",controller.getState().getGroupOwnerReceipts().containsKey(inspectReceipt));assertEquals(inspectReceipt,controller.getState().getGroupOwnerReceipts().get(inspectReceipt).getString("requestId"));
            java.lang.reflect.Field window=PocketWorldController.class.getDeclaredField("groupOwnerWindow");window.setAccessible(true);String old=(String)window.get(controller);controller.leaveOwnerDomain("groups");java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{assertThrows(java.util.concurrent.ExecutionException.class,()->worker.submit(()->app.groupOwnerWorkflows.snapshot(old)).get(3,TimeUnit.SECONDS));}finally{worker.shutdownNow();}
        }finally{if(activity!=null)activity.pause().stop().destroy();app.features.close();server.stop(0);java.security.Security.removeProvider("GroupMountedKeyStore");}
    }
}
